// The site buildings of winroute C, "Bouwproject" (assets/src/sites.json, split in assets/src/sites/*.json, generated by
// scripts/gen-sites.ts): an old ruined strip mall with four restorable parts, each a ruin and a restored building on the
// same footprint. Footprints exact, real-scale sizes (doors 2.1 m or more, the water tower 16 to 20 m), three LODs inside
// the building budget, the ruin without team colour and in rust colours, the restored building with the team_trim mask,
// all eight in the manifest, and assets/dist is the build of this config.
import { readFileSync } from 'node:fs';
import { basename, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { beforeAll, describe, expect, it } from 'vitest';
import { buildSites, FLAT_MATERIALS } from '../scripts/gen-sites.js';
import { splitConfig } from '../scripts/splitConfig.js';
import { listJsonFragments, readSplitJson, splitJsonDir } from '../src/splitJson.js';
import { BUDGETS } from '../src/budgets.js';
import { assetEntrySchema, manifestSchema, type AssetEntry } from '../src/manifest.js';
import { buildRobots, loadRobotsConfig, parseRobots, type RobotsResult } from '../src/robots.js';
import {
  surfaceKindOfMaterial,
  type SurfaceKind,
} from '../../../packages/render/src/look/surfaces.js';

const repo = fileURLToPath(new URL('../../../', import.meta.url));
const configPath = join(repo, 'assets/src/sites.json');
const config = loadRobotsConfig(configPath);

/** The four parts of the strip mall: footprint in cells (metres) and the contract for the size of the model. */
const PARTS = {
  supermarket: { w: 25, h: 15, height: [5.5, 8] },
  gas_station: { w: 15, h: 11, height: [5, 7] },
  garage: { w: 13, h: 11, height: [5.5, 7.5] },
  water_tower: { w: 7, h: 7, height: [16, 20] },
} as const;
const IDS = Object.keys(PARTS).flatMap((part) => [`site_${part}_ruin`, `site_${part}_restored`]);

const SURFACE: Record<string, SurfaceKind> = {
  concrete: 'concrete',
  concrete_ruin: 'concrete',
  concrete_dark: 'concrete',
  rust_metal: 'rustMetal',
  rust_dark: 'rustMetal',
  rust_roof: 'rustMetal',
  metal: 'paintedMetal',
  metal_light: 'paintedMetal',
  metal_dark: 'paintedMetal',
  metal_hazard: 'paintedMetal',
  metal_blue: 'paintedMetal',
  metal_red: 'paintedMetal',
  roof_tar: 'roofing',
  rubber: 'leather',
  lens_glass: 'lens',
  lens_amber: 'lens',
  opening: 'leather',
  team_trim: 'paintedMetal',
};

let built: RobotsResult;
beforeAll(async () => {
  built = await buildRobots(config, 'sites.json');
}, 300_000);

const manifest = manifestSchema.parse(
  JSON.parse(readFileSync(join(repo, 'assets/dist/manifest.json'), 'utf8')),
);
const entry = (id: string): AssetEntry => manifest.assets.find((a) => a.id === id)!;
const size = (e: AssetEntry): [number, number, number] => [
  e.bounds.max[0] - e.bounds.min[0],
  e.bounds.max[1] - e.bounds.min[1],
  e.bounds.max[2] - e.bounds.min[2],
];
const materialsOf = (id: string): string[] => [
  ...new Set(config.buildings[id]!.parts.flatMap((p) => ('material' in p ? [p.material] : []))),
];

describe('sites.json', () => {
  it('has a ruin and a restored building for each of the four parts, all buildings', () => {
    expect(Object.keys(config.buildings).sort()).toEqual([...IDS].sort());
    expect(Object.keys(config.units)).toEqual([]);
    expect(Object.keys(config.attachments)).toEqual([]);
  });

  it('is what scripts/gen-sites.ts generates (edit the script, not the JSON)', () => {
    expect(readSplitJson(configPath)).toEqual(JSON.parse(JSON.stringify(buildSites())));
    expect(listJsonFragments(splitJsonDir(configPath)).map((file) => basename(file))).toEqual(
      splitConfig(buildSites()).map((fragment) => fragment.name),
    );
  });

  it('gives ruin and restored of a part the same footprint, exactly as specified', () => {
    for (const [part, want] of Object.entries(PARTS))
      for (const state of ['ruin', 'restored'])
        expect(config.buildings[`site_${part}_${state}`]!.footprint, `${part} ${state}`).toEqual({
          w: want.w,
          h: want.h,
        });
  });

  it('marks the ruins teamless: no team material in a ruin, team_trim (and only that) when restored', () => {
    for (const id of IDS) {
      const teamNames = materialsOf(id).filter((m) => /team/i.test(m));
      if (id.endsWith('_ruin')) {
        expect(config.buildings[id]!.teamless, id).toBe(true);
        expect(teamNames, id).toEqual([]);
      } else {
        expect(config.buildings[id]!.teamless, id).toBeUndefined();
        expect(teamNames, id).toEqual(['team_trim']);
      }
    }
  });

  it('rejects a team material in a ruin and a missing one in a restored building', () => {
    const raw = readSplitJson(configPath) as {
      buildings: Record<string, { parts: { material?: string }[] }>;
    };
    const withTeam = structuredClone(raw);
    withTeam.buildings.site_garage_ruin!.parts[0]!.material = 'team_trim';
    expect(() => parseRobots(withTeam)).toThrow(/ruine zonder eigenaar/);
    const withoutTeam = structuredClone(raw);
    for (const p of withoutTeam.buildings.site_garage_restored!.parts)
      if (p.material === 'team_trim') p.material = 'metal';
    expect(() => parseRobots(withoutTeam)).toThrow(/team-materiaal/);
  });

  it('uses only materials from flatMaterials, uses every one of them, and names follow the surface kinds', () => {
    const used = new Set(IDS.flatMap(materialsOf));
    expect([...used].sort()).toEqual(Object.keys(config.flatMaterials).sort());
    expect(Object.keys(config.flatMaterials).sort()).toEqual(Object.keys(SURFACE).sort());
    expect(Object.keys(FLAT_MATERIALS).sort()).toEqual(Object.keys(SURFACE).sort());
    for (const [name, kind] of Object.entries(SURFACE))
      expect(surfaceKindOfMaterial(name), name).toBe(kind);
  });

  it('paints the ruins in rust and old concrete, most parts', () => {
    for (const id of IDS.filter((i) => i.endsWith('_ruin'))) {
      const parts = config.buildings[id]!.parts;
      const weathered = parts.filter(
        (p) => 'material' in p && /^(rust_|concrete_)/.test(p.material),
      );
      expect(weathered.length / parts.length, id).toBeGreaterThan(0.6);
    }
  });
});

describe('build', () => {
  it('builds all eight without errors', () => {
    expect(built.reports.flatMap((r) => r.errors)).toEqual([]);
    expect(built.entries.map((e) => e.id).sort()).toEqual([...IDS].sort());
  });

  for (const id of IDS)
    it(`${id}: footprint in the entry, model inside it, real-scale height, three LODs inside the building budget`, () => {
      const e = built.entries.find((x) => x.id === id)!;
      expect(() => assetEntrySchema.parse(e)).not.toThrow();
      const part = id.replace(/^site_/, '').replace(/_(ruin|restored)$/, '') as keyof typeof PARTS;
      const want = PARTS[part];
      expect(e.kind).toBe('building');
      expect(e.footprint).toEqual({ w: want.w, h: want.h });
      const [w, h, d] = size(e);
      expect(w).toBeLessThanOrEqual(want.w * 1.05);
      expect(d).toBeLessThanOrEqual(want.h * 1.05);
      expect(w).toBeGreaterThanOrEqual(want.w * 0.9);
      expect(d).toBeGreaterThanOrEqual(want.h * 0.9);
      expect(h).toBeGreaterThanOrEqual(want.height[0]);
      expect(h).toBeLessThanOrEqual(want.height[1]);
      expect(e.bounds.min[1]).toBeCloseTo(0, 2);
      expect(e.lods.map((l) => l.level)).toEqual([0, 1, 2]);
      e.lods.forEach((lod, level) => {
        expect(lod.triangles).toBeGreaterThan(0);
        expect(lod.triangles).toBeLessThanOrEqual(BUDGETS.buildingMaxTris[level]!);
      });
      expect(e.lods[0].triangles).toBeGreaterThan(e.lods[1].triangles);
      expect(e.lods[1].triangles).toBeGreaterThan(e.lods[2].triangles);
      // The team colour is the manifest's teamMaterials: the mask on a restored building, nothing on a ruin.
      expect(e.teamMaterials).toEqual(id.endsWith('_ruin') ? [] : ['team_trim']);
    });

  it('the water tower is between 16 and 20 m, standing, ruin and restored alike', () => {
    for (const id of ['site_water_tower_ruin', 'site_water_tower_restored']) {
      const h = size(built.entries.find((e) => e.id === id)!)[1];
      expect(h, id).toBeGreaterThanOrEqual(16);
      expect(h, id).toBeLessThanOrEqual(20);
    }
  });

  it('keeps the silhouette: a ruin is within 10 percent of its restored twin in width and depth, and about as high', () => {
    for (const part of Object.keys(PARTS)) {
      const ruin = size(built.entries.find((e) => e.id === `site_${part}_ruin`)!);
      const restored = size(built.entries.find((e) => e.id === `site_${part}_restored`)!);
      expect(ruin[0] / restored[0], part).toBeGreaterThan(0.9);
      expect(ruin[0] / restored[0], part).toBeLessThan(1.1);
      expect(ruin[2] / restored[2], part).toBeGreaterThan(0.9);
      expect(ruin[2] / restored[2], part).toBeLessThan(1.1);
      expect(ruin[1] / restored[1], part).toBeGreaterThan(0.85);
      expect(ruin[1] / restored[1], part).toBeLessThan(1.1);
    }
  });

  it('is deterministic: a second build gives the same bytes', async () => {
    const again = await buildRobots(config, 'sites.json');
    expect([...again.outputs.keys()].sort()).toEqual([...built.outputs.keys()].sort());
    for (const [path, data] of built.outputs)
      expect(Buffer.compare(Buffer.from(data), Buffer.from(again.outputs.get(path)!)), path).toBe(
        0,
      );
    expect(again.entries).toEqual(built.entries);
  }, 300_000);
});

describe('real scale: doors are 2.1 m or more, a storey is about 3 m', () => {
  const restored = (part: string) => config.buildings[`site_${part}_restored`]!.parts;

  it('every dark door opening of a restored building is at least 2.1 m high', () => {
    for (const part of Object.keys(PARTS)) {
      const doors = restored(part).filter(
        (p) => p.type === 'box' && p.material === 'opening' && p.size[0] >= 0.9,
      );
      for (const p of doors)
        if (p.type === 'box') expect(p.size[1], part).toBeGreaterThanOrEqual(2.1);
    }
    const entrances = restored('supermarket').filter(
      (p) => p.type === 'box' && p.material === 'opening',
    );
    expect(entrances.length).toBeGreaterThanOrEqual(2); // the shop entrance and the back door
  });

  it('the garage has two roller doors of at least 3 x 3.4 m, each with a team stripe', () => {
    const doors = restored('garage').filter(
      (p) => p.type === 'box' && p.material === 'metal_light' && p.size[0] >= 3 && p.size[1] >= 3.4,
    );
    expect(doors).toHaveLength(2);
    const stripes = restored('garage').filter(
      (p) => p.type === 'box' && p.material === 'team_trim' && p.size[0] >= 3,
    );
    expect(stripes.length).toBeGreaterThanOrEqual(2);
  });

  it('the gas station canopy is 14 to 15 m long and 10 m deep on pillars of about 5 m', () => {
    const canopy = restored('gas_station').find(
      (p) => p.type === 'box' && p.material === 'metal_light' && p.size[0] > 14,
    );
    expect(canopy && canopy.type === 'box' && canopy.size[0]).toBeGreaterThanOrEqual(14);
    expect(canopy && canopy.type === 'box' && canopy.size[2]).toBeCloseTo(10, 0);
    const pillars = restored('gas_station').filter(
      (p) => p.type === 'box' && p.material === 'metal_light' && p.size[0] < 1 && p.size[1] > 4.5,
    );
    expect(pillars).toHaveLength(4);
  });

  it('every building is higher than a door and than the 1.8 m character', () => {
    for (const id of IDS) expect(size(entry(id))[1], id).toBeGreaterThan(2.1);
  });
});

describe('assets/dist is the build of sites.json', () => {
  it('has the same LOD bytes as a fresh build and the same manifest entries', () => {
    for (const [path, data] of built.outputs) {
      const committed = readFileSync(join(repo, 'assets/dist', path));
      expect(Buffer.compare(Buffer.from(data), committed), path).toBe(0);
    }
    for (const e of built.entries) expect(entry(e.id), e.id).toEqual(e);
    expect(IDS.every((id) => manifest.assets.some((a) => a.id === id))).toBe(true);
  });
});

describe('manifest schema', () => {
  it('accepts a building with an empty teamMaterials (a ruin) and rejects one without the field', () => {
    const e = entry('site_garage_ruin');
    expect(() => assetEntrySchema.parse(e)).not.toThrow();
    const missing: Record<string, unknown> = { ...e };
    delete missing.teamMaterials;
    expect(() => assetEntrySchema.parse(missing)).toThrow(/teamMaterials/);
  });

  it('still wants a team material from a rigid unit', () => {
    const unit = {
      id: 'x',
      kind: 'rigid-unit',
      rigid: true,
      bounds: { min: [0, 0, 0], max: [1, 1, 1] },
      lods: [0, 1, 2].map((level) => ({ level, path: `x/lod${level}.glb`, triangles: 10 })),
      sockets: {},
      animations: [],
      boneCount: 0,
      teamMaterials: [],
    };
    expect(() => assetEntrySchema.parse(unit)).toThrow(/team-materiaal/);
  });
});
